    return (runs && runs.workflow_runs) || [];
}

function headWorkflowRunsSafe(repoInfo, headSha) {
    // headWorkflowRuns + fail-OPEN wrapper: a probe error must not kill
    // the action (worst case: one rerun too many — the same worst case
    // the dispatch guard accepts). null = the probe failed; callers that
    // still need the rollup refetch it themselves.
    try {
        return headWorkflowRuns(repoInfo, headSha);
    } catch (e) {
        console.warn('  ⚠️  head-run probe failed: ' + (e.message || e));
        return null;
    }
}

// ─── Check-run zombie probe (gh-842) ────────────────────────────────────────
//
// Live fa #1457 (2026-10-10): a dispatched CI run cancelled while queued
// (gh-748 twin-guard family) left its `in_progress` check runs on the head
// forever; branch protection takes the LATEST check-run per (context, head),
// so the ghosts held mergeStateStatus=BLOCKED ~2h even though the head ALSO
// carried green terminal entries from the earlier run 38057801418. The tick
// read its rollup green and the green-cover guard (skipIfGreenCi) concluded
// "the blocker is not this CI" — no re-dispatch ever fired. The gh-821
// run-level zombie sweep missed it: the newest EXISTING dispatched run was
// the old green one. This probe closes that gap at the CHECK-RUN level.
//
// Two reads, both in the established fail-open probe family:
//   - the head's check runs (bridge tool — the same REST list
//     computePrStatus falls back to);
//   - the head's run rollup (headWorkflowRunsSafe) as the resolver source:
//     a check-run's backing run is looked up BY ID (parsed from its
//     details_url); ABSENT from the head's list is the 404-equivalent
//     (deleted runs simply do not appear).
// Probe failure on EITHER side ⇒ null (caller keeps the legacy behavior —
// the green-cover skip stands; a degraded read must not turn into a
// re-dispatch churn, and the next tick retries with a healthy API).

function headCheckRunsSafe(repoInfo, headSha) {
    try {
        var res = github_get_commit_check_runs({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            commitSha: headSha
        });
        var parsed = mcpParse(res);
        return (parsed && parsed.check_runs) || [];
    } catch (e) {
        console.warn('  ⚠️  head check-run probe failed: ' + (e.message || e));
        return null;
    }
}

function headCheckRunZombies(repoInfo, headSha) {
    // → null (probe degraded — caller keeps legacy behavior) | the
    // classify() result {zombies, live, settled, unresolvable}.
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    if (!checkRuns.length) return { zombies: [], live: 0, settled: 0, unresolvable: 0 };
    var runs = headWorkflowRunsSafe(repoInfo, headSha);
    if (runs === null) return null;
    var byId = {};
    runs.forEach(function (r) {
        if (r && r.id !== undefined && r.id !== null) byId[String(r.id)] = r;
    });
    return checkRunZombiesModule.classify(checkRuns, function (runId) {
        var hit = byId[String(runId)];
        return hit === undefined ? null : hit;
    }, Date.now(), {
        staleNoRunnerMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieStaleMinutes,
        runConcludedGraceMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieGraceMinutes
    });
}

// Placeholder probe (gh-852) — the check-run-level twin of
// headCheckRunZombies, at the PLACEHOLDER grace (default 3 min), not the
// 30-min zombie staleness: GitHub mints pending placeholder check-runs
// ~20s after a dispatch that queued without materializing a job; while
// they are young they are indistinguishable from a live dispatch's fresh
// bridge stamp (both link-less), so only the short grace safely separates
// them. Same transport contract: null = the check-run probe failed — the
// caller keeps the legacy behavior (fail safe toward live).
function headPlaceholders(repoInfo, headSha) {
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    return checkRunZombiesModule.placeholders(checkRuns, Date.now(), {
        placeholderMinutes: (RUN_JOB_PARAMS || {}).checkRunPlaceholderMinutes
    });
}

// Orphan probe (gh-865) — the numeric-id twin of headPlaceholders: PENDING
// check-runs whose OWNING RUN has concluded (any conclusion, past the
// propagation grace). Live fa #1457 head fd1b9aa2: GitHub minted in_progress
// placeholder check-runs WITH run ids on the kicker suite (run 38164305157,
// concluded success) after the ~10-13 min speculative-placeholder window
// expired; headPlaceholders() keys on the ABSENT run id so the gh-857
// conclude step never saw them and they pinned the gate 4+ hours. Same
// transport contract as the sibling probes: null = the check-run probe
// failed — the caller keeps the legacy behavior (fail safe toward live).
function headOrphanedRunChecks(repoInfo, headSha) {
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    if (!checkRuns.length) return [];
    var runs = headWorkflowRunsSafe(repoInfo, headSha);
    if (runs === null) return null;
    var byId = {};
    runs.forEach(function (r) {
        if (r && r.id !== undefined && r.id !== null) byId[String(r.id)] = r;
    });
    return checkRunZombiesModule.orphanedRunChecks(checkRuns, function (runId) {
        var hit = byId[String(runId)];
        return hit === undefined ? null : hit;
    }, Date.now(), {
        runConcludedGraceMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieGraceMinutes
    });
}

// ── gh-857: in-place placeholder conclusion ────────────────────────────────
//
// Live fa #1457 (head fd1b9aa2): the placeholder check-run (18:51:25)
// pinned the gate forever while the SM's own green stamp (19:04:35) never
// overrode it — branch protection takes the LATEST check-run per
// (context, head), so a pending placeholder wins over any later stamp.
// The gh-852 fresh-sha reset cures the pin but burns a full validation
// cycle; when the head already carries the real green verdict the cheap
// cure is to conclude the placeholder IN PLACE via the Checks API PATCH.
//
// greenCoverRun — the "real green verdict" probe: the newest
// COMPLETED-SUCCESS dispatched validation run on this head. The
// placeholder conclusion MIRRORS this verdict (AC3: red/absent never
// concludes a placeholder green — the caller must only conclude with a
// success cover; a 'skipped' real stamp is never a green cover either).
// CANCELLED is never a verdict (gh-755). Fail CLOSED (null): no verdict,
// no conclusion.
function greenCoverRun(repoInfo, ciWorkflow, headSha) {
    try {
        var res = cli_execute_command({
            command: 'gh api "repos/' + repoInfo.owner + '/' +
                     repoInfo.repo +
                     '/actions/workflows/' + ciWorkflow +
                     '/runs?head_sha=' + headSha +
                     '&event=workflow_dispatch&per_page=5"'
        });
        var runs = mcpParse((res || {}).output ||
                            (res || {}).stdout || res);
        var list = ((runs && runs.workflow_runs) || []).filter(function (r) {
            return r.status === 'completed' && r.conclusion === 'success';
        });
        if (!list.length) return null;
        list.sort(function (a, b) {
            return new Date(b.updated_at || b.created_at).getTime() -
                   new Date(a.updated_at || a.created_at).getTime();
        });
        return list[0];
    } catch (e) {
        console.warn('  ⚠️  green-cover probe failed: ' + (e.message || e));
        return null;
    }
}

// gh-857 conclusion transport — PATCH each placeholder check-run to
// completed/success, output referencing the covering run. Mirrors the
// gh-848 belt (concludeOrphanedCheckRuns): the check-runs belong to the
// github-actions App, so the PATCH rides the workflow token
// (jobParams.silentToken) with checks:write; the tick PAT would 403.
// Returns { concluded, rejected } — rejected carries the first failure
// message (403 ownership, missing id, transient): the caller logs the
// evidence and falls back to the gh-852 fresh-sha reset.
function concludePlaceholderCheckRuns(repoInfo, placeholders, coverRun) {
    var out = { concluded: 0, rejected: null };
    if (!placeholders || !placeholders.length) return out;
    var coverUrl = (coverRun && (coverRun.html_url || coverRun.url))
        ? String(coverRun.html_url || coverRun.url) : null;
    var coverLine = 'Concluded in place by the SM tick (gh-857) — the head\'s' +
        ' dispatched validation run concluded success' +
        (coverUrl ? (': ' + coverUrl) : '') +
        '. The gh-852 fresh-sha reset is the fallback cure.';
    var appToken = (RUN_JOB_PARAMS || {}).silentToken;
    var sourceTok = (RUN_JOB_PARAMS || {}).sourceToken;
    var swapped = false;
    if (appToken) {
        try {
            set_env_variable('GH_TOKEN', appToken);
            swapped = true;
        } catch (eSwap) {
            console.warn('  ⚠️  gh-857 token swap failed, conclusion uses the' +
                         ' PAT (may 403): ' + (eSwap.message || eSwap));
        }
    }
    try {
        placeholders.forEach(function (ph) {
            if (!ph || ph.id === null || ph.id === undefined) {
                if (!out.rejected) out.rejected = 'check-run id missing (cannot PATCH)';
                return;
            }
            if (DRY) {
                console.log('  🧪 [dry] conclude placeholder check-run ' + ph.id +
                            ' ("' + (ph.name || '?') + '") completed/success (gh-857)');
                return;
            }
            try {
                cli_execute_command({
                    command: 'gh api -X PATCH repos/' + repoInfo.owner +
                        '/' + repoInfo.repo + '/check-runs/' + ph.id +
                        ' -f status=completed' +
                        ' -f conclusion=success' +
                        (coverUrl ? (' -f details_url="' + coverUrl + '"') : '') +
                        ' -f "output[title]=SM concluded a placeholder check-run (gh-857)"' +
                        ' -f "output[summary]=' + coverLine + '"'
                });
                out.concluded++;
            } catch (ePatch) {
                if (!out.rejected) out.rejected = (ePatch && ePatch.message) || String(ePatch);
            }
        });
    } finally {
        if (swapped && sourceTok) {
            try { set_env_variable('GH_TOKEN', sourceTok); } catch (e3) {}
        }
    }
    return out;
}

// gh-852 AC2 pool-free probe: a fresh-sha reset cures the placeholder-pinned
// gate ONLY when the next dispatch materializes its first job immediately —
// a queued dispatch mints FRESH placeholders on the new head ~20s later and
// the pathology re-arms. "No ACTIVE run repo-wide" is the conservative
// proxy for the ticket's "no in_progress macos/ubuntu-arm runs" (self-hosted
// runner labels ride job objects, not the run list). Also subsumes the
// gh-798 leg guard: an in-flight ai-teammate leg IS an active run, so a
// pool-free read proves no leg owns the head either. Returns
// true (pool free) | false (busy) | null (probe failed — callers fail
// CLOSED: one deferred reset costs a tick, a reset under a busy pool
// re-mints the placeholders it exists to clear).
function repoPoolFree(repoInfo) {
    try {
        var runs = mcpParse(github_list_workflow_runs({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            perPage: 50
        })) || {};
        var list = runs.workflow_runs || runs.workflowRuns || [];
        var busy = list.some(function (r) {
            return r && validationLivenessModule.ACTIVE_RUN_STATES
                .indexOf(String(r.status || '').toLowerCase()) !== -1;
        });
        return !busy;
    } catch (ePool) {
        console.warn('  ⚠️  pool-free probe failed: ' + (ePool.message || ePool));
        return null;
    }
}


function hasActiveHeadRun(runs) {
    // hasActiveDispatchedRun semantics, widened to every run on the head:
    // any queued/in-progress/waiting/pending run means the state is about
    // to move on its own (a fresh kicker stamps the contexts, a validation
    // dispatch re-runs them) — rerunning cancelled runs under it would
    // only stack. Takes the pre-fetched head rollup (the action fetches
    // once and shares it with the target mapping — #695 review); a null
    // (failed probe) reads as no active run — fail OPEN. The ACTIVE
    // vocabulary comes from js/common/validationLiveness.js (gh-821 round-2
    // review: one constant, not parallel inline lists that drift).
    return (runs || []).some(function (r) {
        return validationLivenessModule.ACTIVE_RUN_STATES.indexOf(r.status) !== -1;
    });
}

// gh-798 (live fa PR #1420 rework leg, run 37828431528): the in-flight-leg
// exclusion for update_branch. A rework/review ai-teammate leg dispatched
// with workflowRef={branch} lands ON the PR head (its run head_sha IS the
// PR head), so an ACTIVE run of the leg workflow in the head rollup means
// the head is owned mid-run — the leg's timer pushes WIP auto-saves to that
// ref, and a silent refresh merged under it rejects the leg's next push
// non-fast-forward ("timer: git push failed" surfaced to the running
// agent). Same invariant as the ai_validating exclusion: a head with a leg
// in flight must not move. hasActiveHeadRun semantics (any
// queued/in_progress/waiting/pending run), NARROWED to the leg workflow
// path so unrelated CI on the head never blocks freshness, plus the same
// stale-zombie window the dispatch guard applies (a leg stuck 'queued' for
// hours ages out). Takes the pre-fetched head rollup (headWorkflowRunsSafe —
// the probe itself fails CLOSED in update_branch, unlike the rerun rule's
// fail-open read: one deferred refresh costs a tick, racing a live leg
// costs the leg's whole push stream).
function hasActiveLegRun(runs, workflowFile) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        var status = r.status;
        if (status !== 'queued' && status !== 'in_progress' &&
            status !== 'waiting' && status !== 'pending') return false;
        if (status !== 'in_progress' && isStaleNonRunningWorkflowRun(r, status)) return false;
        var p = String(r.path || '');
        return p.length >= suffix.length &&
            p.slice(p.length - suffix.length) === suffix;
    });
}

